entries[206005] = { ["name"] = "Wirt's Fightin' Leg", ["text"] = "Cosmetic\nBinds when equipped\nOne-Hand Mace\n1 Damage Speed 2.60\n(0.4 damage per second)\nDurability 20 / 20\n\"Who's Wirt?\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[206006] = { ["name"] = "Earth-Warder's Thanks", ["text"] = "Binds when picked up\nUse: Grants 2500 reputation with the Loamm Niffen.\n\"A flower, grown from the earth that the Earth-Warder has sworn to protect, as well as a gift to you for your heroism.\"\nSell Price:" }
entries[206007] = { ["name"] = "Treasure Nabbin' Bag", ["text"] = "Cosmetic\nBinds to Warband\nBack\n1 Armor\n\"How do they get all that treasure in there?\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[206008] = { ["name"] = "Nightmare Banner", ["text"] = "Binds when picked up\nToy\nUse: Plant the Nightmare Banner. (3 Min Cooldown)\n\"It's the banner of your dreams. Bad dreams.\"" }
entries[206009] = { ["name"] = "Ouroboros Tablet", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Flesh.\n\"Complex diagrams coat the surface, with four designs stretching past the stone's edges. An eloquently designed ouroboros lies engraved in the center.\"" }
entries[206010] = { ["name"] = "Designs of Flesh", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Flesh.\n\"Decorated in ancient symbols of blood and water.\"" }
entries[206011] = { ["name"] = "Designs of Bone", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Bone.\n\"Decorated in ancient symbols of bone and earth.\"" }
entries[206012] = { ["name"] = "Designs of Mind", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Mind.\n\"Decorated in ancient symbols of mind and fire.\"" }
entries[206013] = { ["name"] = "Designs of Soul", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Soul.\n\"Decorated in ancient symbols of soul and air.\"" }
entries[206014] = { ["name"] = "Ouroboros Tablet", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Bone.\n\"Circular designs show a large spiral pattern starting from the left side. Symbols of water and blood flow into it and the missing spaces along the bottom.\"" }
entries[206015] = { ["name"] = "Ouroboros Tablet", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Mind.\n\"Symbols of bone and earth line the pathway of the spiral design as it continues up from the bottom and into the missing right side.\"" }
entries[206016] = { ["name"] = "Ouroboros Tablet", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with Designs of Soul.\n\"As symbols of mind and fire wrap around the carved spiral, they move inward and up into the open space at the top.\"" }
entries[206017] = { ["name"] = "Ouroboros Tablet", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with the Kob'rok's Luminescent Scale.\n\"Delicately drawn symbols of soul and air decorate the top as the spiral continues inward. The ouroboros in the center glows brightly as a violet energy is siphoned through the spiral and into the center.\"" }
entries[206018] = { ["name"] = "Baa'lial Soulstone", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss Baa'l.\nRequires level 1 to 80 ( 80)\nSell Price:" }
entries[206019] = { ["name"] = "Abandoned Reserve Chute", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Tailoring Knowledge by 3.\nRequires Dragon Isles Tailoring (25)\n\"Luckily for someone it's just the reserve chute. You could learn a lot from studying the stitchwork!\"" }
entries[206020] = { ["name"] = "Enmity Hood", ["text"] = "Cosmetic\nBinds to Warband\nHead Cosmetic\n\"This object emits waves of hatred.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[206021] = { ["name"] = "Kob'rok's Luminescent Scale", ["text"] = "Binds when picked up\nUse: Combine the Ouroboros Tablet with the Kob'rok's Luminescent Scale.\n\"A suitable sacrifice.\"" }
entries[206022] = { ["name"] = "Anduin's Lucky Hearthstone Card", ["text"] = "Quest Item\n\"An old-looking Common card depicting a Stormwind Guard with lightly tattered edges.\"" }
entries[206025] = { ["name"] = "Used Medical Wrap Kit", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Tailoring Knowledge by 3.\nRequires Dragon Isles Tailoring (25)\n\"Most of the supplies have been used, but some of the medical bandages remain.\"" }
entries[206027] = { ["name"] = "Reins of the Felcrystal Scorpion", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The results of a fel infusion experiment with one of Skorpyron's offspring.\"\nTrading Post" }
entries[206028] = { ["name"] = "Chest of Gold", ["text"] = "Binds when picked up\n\"Contains 1000 gold.\"\n<Right Click to Open>" }
entries[206030] = { ["name"] = "Exquisitely Embroidered Banner", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Tailoring Knowledge by 3.\nRequires Dragon Isles Tailoring (25)\n\"The quality of this banner is positively breathtaking. This was crafted by quite the artisan.\"" }
entries[206031] = { ["name"] = "Intricate Zaqali Runes", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Inscription Knowledge by 3.\nRequires Dragon Isles Inscription (25)\n\"Ancient magic emanates from the runes carved upon the surface.\"" }
entries[206033] = { ["name"] = "Untranslated Obsidian Tome", ["text"] = "Binds when picked up\n\"An untranslated tome discovered by Wrathion in the Obsidian Citadel. He gifted it to you, believing you would pursue its mystery.\"\n<Right Click to Read>" }
entries[206034] = { ["name"] = "Hissing Rune Draft", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Inscription Knowledge by 3.\nRequires Dragon Isles Inscription (25)\n\"A low hissing fills your mind. Is it the rock vipers nearby, or the rune?\"" }
entries[206035] = { ["name"] = "Ancient Research", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Inscription Knowledge by 3.\nRequires Dragon Isles Inscription (25)\n\"Surprisingly well preserved, this text documents research into various runes and magics.\"" }
entries[206037] = { ["name"] = "Ruby Flightstone", ["text"] = "Binds when picked up\n\"Once this contained the power of flightstones. Now it's a beautiful paperweight.\"\nSell Price:" }
entries[206038] = { ["name"] = "Flamin' Ring of Flashiness", ["text"] = "Binds when picked up\nToy\nUse: Put on a flashy show with an explosive conclusion. (1 Hour Cooldown)\n\"Fire works as an easy way to impress the crowd.\"" }
