entries[206043] = { ["name"] = "Fyrakk's Frenzy", ["text"] = "Binds when picked up\nToy\nUse: Summon the essence of Fyrakk to unleash a deep breath, devastating critters caught in the flames. (10 Min Cooldown)" }
entries[206044] = { ["name"] = "Obsidian Gladiator's Axe", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 Damage Speed 2.60\n(0.4 damage per second)\nDurability 30 / 30\nEarn the rank of Elite during Dragonflight Season 2.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[206046] = { ["name"] = "Void-Touched Curio", ["text"] = "Binds when picked up\n\"A fascinating and menacing omen. Kaitalla at the Obsidian Rest in Zaralek Cavern may know how to unlock the secrets that lay within.\"\nSell Price:" }
