entries[206138] = { ["name"] = "Scalewarden's Pennant", ["text"] = "Binds when picked up\nUse: Represent your victories with a pennant. (2 Min Cooldown)\n\"Your brave deeds bring great pride to your faction!\"" }
entries[206139] = { ["name"] = "Volatile Crimson Embers", ["text"] = "Binds when picked up\nUse: Infuse yourself with Crimson Power, increasing your damage done by 30% but inflicting yourself with fire, taking Fire damage equal to 1% of your maximum health every 3 sec over 24 sec." }
entries[206140] = { ["name"] = "Soothing Emerald Tea", ["text"] = "Binds when picked up\nUse: Infuse yourself with Emerald Power, healing yourself for 25% and 40% of your maximum health over 15 sec." }
