entries[206144] = { ["name"] = "Curious Primordial Fungus", ["text"] = "Binds when picked up\nUse: Infuse yourself with Primordial Power, reducing magic damage you take by 30%, while shrinking you and reducing your movement speed by 20%.\n\"One side will make you grow shorter, but so will the other.\"" }
entries[206145] = { ["name"] = "Mysterious Time Relic", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 10 to 80 ( 80)\n\"What was Chrono-Lord Deios doing with this?\"" }
