entries[206156] = { ["name"] = "Grotto Netherwing Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\"Teaches you how to summon this mount.\"\nSell Price:\n\"After traveling to Outland and back, it's only natural these drakes seek out new skies.\"\nQuest:\nDragon Keeping\nZone:\nEmerald Dream" }
