entries[206160] = { ["name"] = "Madam Shadow's Grimoire", ["text"] = "Quest Item\nUse: Invoke the powers of Madam Shadow's fel soulstone. (12 Sec Cooldown)\n\"A damp and musty tome. Smells vaguely of... sulfur?\"" }
entries[206161] = { ["name"] = "Time-Displaced Toy", ["text"] = "Quest Item\n\"A well-loved squeaky toy misplaced in time.\"" }
entries[206162] = { ["name"] = "Lingering Echo of Tarecgosa", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to transform into Tarecgosa's Visage without need of Dragonwrath.\nTransform into Tarecgosa's Visage, granting you increased movement speed and allowing you to fly.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Farewell, Tarecgosa. A dear sister, hero, student, and teacher. Though blood does not bind us, you will always be family. May your soul find its place soaring among the stars.\"\nQuest:\nRhapsody in Blue" }
