entries[206167] = { ["name"] = "Way of the Wondrous Wavewhisker", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"They say one of these magical fish is born when a fisherfolk dreams of the one that got away... and grows bigger with each retelling of the tale.\"\nIn-Game Shop" }
