entries[206343] = { ["name"] = "Crimson Legend's Pennant", ["text"] = "Binds when picked up\nToy\nUse: Represent your seasonal achievement with a pennant. (2 Min Cooldown)" }
entries[206346] = { ["name"] = "Eva's Journal", ["text"] = "Binds when picked up\nUnique\nUse: Perform a ritual.\n\"A detailed recollection of increasingly horrific events. Many pages remain blank.\"" }
entries[206347] = { ["name"] = "Mannequin Charm", ["text"] = "Binds when picked up\nToy\nUse: Transforms caster to a mannequin from the Trading Post. (10 Min Cooldown)\n\"Represent the Trading Post.\"\nSell Price:" }
entries[206348] = { ["name"] = "Fragmented Flame", ["text"] = "Binds when picked up\nUse: Combine 5 Fragmented Flame together to create a Fragmented Reagent or Shard of Flame.\n\"The shattered remains of a Shard of Flame pillaged in a recent attack.\"\nSell Price:" }
entries[206349] = { ["name"] = "Fragmented Reagent", ["text"] = "Quest Item\nUnique\n\"Fragmented Flames fused together to create something new!\"" }
entries[206350] = { ["name"] = "Radiant Remnant", ["text"] = "Binds when picked up\nRequires Renown Rank 23 with the Hallowfall Arathi.\nRequires Renown Rank 25 with the Hallowfall Arathi.\n\"A valuable reagent used to fuel the light of the keyflames.\"" }
entries[206351] = { ["name"] = "Plans: Truesilver Champion", ["text"] = "Binds when picked up\nUse: Teaches you how to make Truesilver Champion.\nRequires Classic Blacksmithing (300)\nSell Price:\nTruesilver Champion\nBinds when equipped\nTwo-Hand Sword\n6 - 11 Damage Speed 3.60\n(2.4 damage per second)\nDurability 100 / 100\nChance on hit: Protects the caster with a holy shield.\nSell Price:\nRequires Mithril Bar (30), Truesilver Bar (16), Star Ruby (6), Breath of Wind (4), Solid Grinding Stone (8), Thick Leather (6)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[206352] = { ["name"] = "Plans: The Shatterer", ["text"] = "Binds when picked up\nUse: Teaches you how to make The Shatterer.\nRequires Classic Blacksmithing (300)\nSell Price:\nThe Shatterer\nBinds when equipped\nOne-Hand Mace\n4 - 5 Damage Speed 2.60\n(1.7 damage per second)\n+2 Strength\n+2 Stamina\nDurability 90 / 90\nSell Price:\nRequires Mithril Bar (24), Core of Earth (4), Truesilver Bar (6), Citrine (5), Jade (5), Solid Grinding Stone (4), Thick Leather (4)\nOptional Reagents: Optional Reagent Slot (#31)" }
entries[206353] = { ["name"] = "Sentinel's Whistle", ["text"] = "Quest Item\nUse: Summons a hippogryph to quickly fly you from Lunedane to Valdrakken.\n\"A small runewood whistle that produces a sharp, warbling tune.\"" }
entries[206354] = { ["name"] = "Stinky Candle", ["text"] = "Binds when picked up\nUnique\n\"Perfect for those days when you want everyone to leave you alone.\"" }
entries[206355] = { ["name"] = "Tobacco-Filled Candle", ["text"] = "Binds when picked up\nUnique\n\"When the courier is running late, sometimes you must take matters into your own hands.\"" }
entries[206356] = { ["name"] = "Ghost-Warding Candle", ["text"] = "Binds when picked up\nUnique\n\"Supposedly keeps the ghosts away, but evidently that is just a child's story.\"" }
entries[206357] = { ["name"] = "Authentic Andorhal Candle", ["text"] = "Binds when picked up\nUnique\n\"A candle so ordinary it is actually quite suspicious.\"" }
entries[206358] = { ["name"] = "Imported Candle", ["text"] = "Binds when picked up\nUnique\n\"The most impressive detail of this candle is how someone managed to fully carve out \"Corin's Crossing\" on the bottom.\"" }
entries[206359] = { ["name"] = "Caer Darrow Fountain Water", ["text"] = "Binds when picked up\nUnique\n\"Far too viscous to evaporate.\"" }
entries[206360] = { ["name"] = "Undelivered Shipment of Smokes", ["text"] = "Binds when picked up\nUnique\n\"A crate of the finest cigars Ezra Grimm had to offer.\"" }
entries[206361] = { ["name"] = "Trampled Doll", ["text"] = "Binds when picked up\nUnique\n\"A crumpled note shoved into one of the doll's pockets reads: 'To my bestest friend, from Pamela.'\"" }
entries[206362] = { ["name"] = "The Deed to Andorhal", ["text"] = "Binds when picked up\nUnique\n\"Carries a faded seal.\"" }
entries[206363] = { ["name"] = "The Road Ahead", ["text"] = "Binds when picked up\nUnique\n\"A gorgeous painting of the road leading out of Corin's Crossing. The signature \"Renfray\" is carefully inscribed on a corner.\"" }
entries[206364] = { ["name"] = "Eva's Femur", ["text"] = "Binds when picked up\nUnique\n\"Probably not what Eva was expecting you to use for the ritual, but it gets the job done.\"" }
entries[206365] = { ["name"] = "Inert Spectral Essence", ["text"] = "Binds when picked up\nUnique\nUse: Infuse with 5 Essence of Undeath and 3 Dark Runes.\n\"Allowed communication with the deceased of Caer Darrow, long ago.\"" }
entries[206366] = { ["name"] = "Cracked Trophy of Strife", ["text"] = "Binds when picked up\nSell Price:" }
entries[206367] = { ["name"] = "Cracked Trophy of Strife", ["text"] = "Binds when picked up\nSell Price:" }
entries[206368] = { ["name"] = "Wand of Mass Polymorph", ["text"] = "Quest Item\n\"A wand charged up with the ability to cast Polymorph to transform targets into sheep.\"" }
entries[206369] = { ["name"] = "Time Trap", ["text"] = "Quest Item\nUse: Trap an alternate timeline Chromie in temporary stasis in order to synchronize her time signature. (3 Sec Cooldown)\n\"Kept in an ever-revolving mobius strip bandolier.\"" }
