entries[206546] = { ["name"] = "Ancient Plans: Blade of the Fallen Seraph", ["text"] = "Use: Teaches you how to craft Blade of the Fallen Seraph.\nRequires Classic Blacksmithing (300)\nSell Price:\nBlade of the Fallen Seraph\nBinds when equipped\nUnique-Equipped\nOne-Hand Sword\n3 - 7 Damage Speed 2.60\n(1.9 damage per second)\n+2 [Agility or Strength]\n+ 3 Critical Strike\n+ 2 Haste\nDurability 110 / 110\nSell Price:\nRequires Wartorn Scrap (40), Enchanted Thorium Bar (30), Pristine Black Diamond (2), Frozen Rune (8), Large Brilliant Shard (20), Essence of Undeath (16)" }
entries[206547] = { ["name"] = "Ancient Pattern: Bindings of the Harvested Soul", ["text"] = "Use: Teaches you how to craft Bindings of the Harvested Soul.\nRequires Classic Tailoring (300)\nSell Price:\nBindings of the Harvested Soul\nBinds when equipped\nWrist Cloth\n2 Armor\n+2 Intellect\n+3 Stamina\n+ 2 Critical Strike\nDurability 55 / 55\nSell Price:\nRequires Wartorn Scrap (15), Essence of Undeath (10), Felcloth (8), Bolt of Runecloth (6), Frozen Rune (4), Dark Rune (5)" }
entries[206548] = { ["name"] = "Ancient Technique: Encased Frigid Heart", ["text"] = "Use: Teaches you how to craft Encased Frigid Heart.\nRequires Classic Inscription (300)\nSell Price:\nEncased Frigid Heart\nBinds when equipped\nHeld In Off-hand\n+6 Intellect\n+3 Stamina\n+ 2 Versatility\nSell Price:\nRequires Frozen Rune (16), Arcanite Bar (6), Dark Rune (20), Truesilver Bar (16), Essence of Undeath (20)" }
entries[206549] = { ["name"] = "Ancient Plans: The Face of Doom", ["text"] = "Use: Teaches you how to craft The Face of Doom.\nRequires Classic Blacksmithing (300)\nSell Price:\nThe Face of Doom\nBinds when equipped\nOff Hand Shield\n43 Armor\n+2 Strength\n+6 Intellect\n+3 Stamina\n+ 2 Dodge\n+ 1 Versatility\nDurability 120 / 120\nSell Price:\nRequires Wartorn Scrap (60), Truesilver Bar (16), Guardian Stone (9), Blue Sapphire (12), Frozen Rune (7), Arcanite Bar (12)" }
entries[206550] = { ["name"] = "Ancient Plans: Harbinger of Death", ["text"] = "Use: Teaches you how to craft Harbinger of Death.\nRequires Classic Blacksmithing (300)\nSell Price:\nHarbinger of Death\nBinds when equipped\nUnique-Equipped\nOne-Hand Dagger\n2 - 5 Damage Speed 1.80\n(1.9 damage per second)\n+1 Agility\n+1 Stamina\n+ 3 Critical Strike\n+ 2 Haste\nDurability 80 / 80\nSell Price:\nRequires Wartorn Scrap (40), Dense Grinding Stone (40), Arcanite Bar (8), Pristine Black Diamond (6), Essence of Undeath (16)" }
entries[206551] = { ["name"] = "Ancient Design: Frostwyrm's Icy Gaze", ["text"] = "Use: Teaches you how to craft Frostwyrm's Icy Gaze.\nRequires Classic Jewelcrafting (300)\nSell Price:\nFrostwyrm's Icy Gaze\nBinds when equipped\nHeld In Off-hand\n+6 Intellect\n+3 Stamina\n+ 1 Versatility\nSell Price:\nRequires Wartorn Scrap (20), Frozen Rune (8), Pristine Black Diamond (2), Essence of Undeath (40), Ghost Dye (15)" }
entries[206552] = { ["name"] = "Ancient Design: Frostwyrm's Frigid Stare", ["text"] = "Use: Teaches you how to craft Frostwyrm's Frigid Stare.\nRequires Classic Jewelcrafting (300)\nSell Price:\nFrostwyrm's Frigid Stare\nBinds when equipped\nHeld In Off-hand\n+6 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 1 Haste\nSell Price:\nRequires Wartorn Scrap (20), Frozen Rune (8), Blue Sapphire (10), Essence of Undeath (40), Ghost Dye (15)" }
entries[206553] = { ["name"] = "Ancient Plans: Dawn of Demise", ["text"] = "Use: Teaches you how to craft Dawn of Demise.\nRequires Classic Blacksmithing (300)\nSell Price:\nDawn of Demise\nBinds when equipped\nUnique-Equipped\nOne-Hand Sword\n3 - 7 Damage Speed 2.60\n(1.9 damage per second)\n+2 [Agility or Strength]\n+2 Stamina\nDurability 110 / 110\nSell Price:\nRequires Wartorn Scrap (40), Large Fang (8), Enchanted Thorium Bar (16), Essence of Undeath (20), Dark Rune (6), Arcanite Bar (12)" }
entries[206554] = { ["name"] = "Ancient Pattern: Necrotic Gown", ["text"] = "Use: Teaches you how to craft Necrotic Gown.\nRequires Classic Tailoring (300)\nSell Price:\nNecrotic Gown\nBinds when equipped\nChest Cloth\n4 Armor\n+4 Intellect\n+5 Stamina\n+ 2 Versatility\nDurability 165 / 165\nSell Price:\nRequires Wartorn Scrap (50), Essence of Undeath (40), Felcloth (20), Bolt of Runecloth (12), Frozen Rune (12), Dark Rune (15)" }
entries[206555] = { ["name"] = "Ancient Plans: Gauntlets of the Unrelenting", ["text"] = "Use: Teaches you how to craft Gauntlets of the Unrelenting.\nRequires Classic Blacksmithing (300)\nSell Price:\nGauntlets of the Unrelenting\nBinds when equipped\nHands Plate\n8 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Haste\nDurability 55 / 55\nEquip: Disarm duration reduced by 50%.\nSell Price:\nRequires Wartorn Scrap (35), Blood of Innocents , Steel Weapon Chain (2), Star Ruby (4), Arcanite Bar (8), Dark Rune (2)" }
entries[206556] = { ["name"] = "Ancient Pattern: Displacement Boots", ["text"] = "Use: Teaches you how to craft Displacement Boots.\nRequires Classic Leatherworking (300)\nSell Price:\nDisplacement Boots\nBinds when equipped\nFeet Leather\n4 Armor\n+4 [Agility or Intellect]\n+4 Stamina\nDurability 80 / 80\nEquip: Increases your effective stealth level.\nSell Price:\nRequires Wartorn Scrap (35), Enchanted Leather (40), Rugged Leather (20), Cured Rugged Hide (12), Dark Rune (8), Rune Thread (10)" }
entries[206557] = { ["name"] = "Ancient Plans: Death's Gamble", ["text"] = "Use: Teaches you how to craft Death's Gamble.\nRequires Classic Blacksmithing (300)\nSell Price:\nDeath's Gamble\nBinds when equipped\nOff Hand Shield\n42 Armor\n+2 Strength\n+6 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Versatility\nDurability 120 / 120\nSell Price:\nRequires Wartorn Scrap (60), Essence of Undeath (40), Huge Emerald (20), Ghost Dye (60), Arcanite Bar (12)" }
entries[206558] = { ["name"] = "Ancient Plans: Belt of the Mentor", ["text"] = "Use: Teaches you how to craft Belt of the Mentor.\nRequires Classic Blacksmithing (300)\nSell Price:\nBelt of the Mentor\nBinds when equipped\nWaist Plate\n8 Armor\n+2 [Strength or Intellect]\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\nDurability 55 / 55\nSell Price:\nRequires Wartorn Scrap (15), Truesilver Bar (45), Arcanite Bar (8), Azerothian Diamond (4), Essence of Undeath (30)" }
entries[206559] = { ["name"] = "Ancient Schematic: Replaced Servo Arm", ["text"] = "Use: Teaches you how to craft Replaced Servo Arm.\nRequires Classic Engineering (300)\nSell Price:\nReplaced Servo Arm\nBinds when equipped\nOne-Hand Mace\n4 - 6 Damage Speed 2.60\n(1.9 damage per second)\nDurability 110 / 110\nEquip: Chance to discharge electricity causing 2 Nature damage to your target.\nSell Price:\nRequires Wartorn Scrap (40), Essence of Undeath (20), Delicate Arcanite Converter (12), Unstable Trigger (20), Gyrochronatom (16), Fused Wiring (200)" }
entries[206560] = { ["name"] = "Ancient Plans: Stygian Shield", ["text"] = "Use: Teaches you how to craft Stygian Shield.\nRequires Classic Blacksmithing (300)\nSell Price:\nStygian Shield\nBinds when equipped\nOff Hand Shield\n42 Armor\n+2 Strength\n+6 Intellect\n+3 Stamina\nDurability 120 / 120\nEquip: When struck has a 15% chance of reducing the attacker's movement speed by 50% for 5 secs. Chance to fizzle against targets over level 49. (Proc chance: 15%)\nSell Price:\nRequires Wartorn Scrap (60), Gold Bar (20), Arcanite Bar (6), Ghost Dye (16), Large Opal (20)" }
entries[206561] = { ["name"] = "Ancient Pattern: Lucien's Lost Soles", ["text"] = "Use: Teaches you how to craft Lucien's Lost Soles.\nRequires Classic Leatherworking (300)\nSell Price:\nLucien's Lost Soles\nBinds when equipped\nFeet Leather\n4 Armor\n+2 [Agility or Intellect]\n+4 Stamina\n+ 3 Haste\nDurability 60 / 60\nSell Price:\nRequires Rugged Leather (16), Cured Rugged Hide (4), Essence of Undeath (6), Rune Thread (6)" }
entries[206562] = { ["name"] = "Shroud of Forbidden Magic", ["text"] = "Cosmetic\nBinds when equipped\nHead Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[206563] = { ["name"] = "Ancient Pattern: Shroud of Forbidden Magic", ["text"] = "Use: Teaches you how to craft Shroud of Forbidden Magic.\nRequires Classic Tailoring (300)\n\nShroud of Forbidden Magic\nCosmetic\nBinds when equipped\nHead Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:\nRequires Wartorn Scrap (200), Essence of Undeath (100), Felcloth (50), Large Brilliant Shard (60), Dark Rune (25), Ghost Dye (20)" }
entries[206564] = { ["name"] = "Time-Displaced Titanic Disc", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"This item is clearly of titan origin. Despite the saliva dripping from it, it still appears to be functional.\"" }
entries[206565] = { ["name"] = "Plagued Grain", ["text"] = "Binds when picked up\nToy\nUse: Place down a crate of ordinary grain for 3 min. Nobody will suspect a thing. (2 Hrs Cooldown)\n\"A crate postmarked for Light's Hope Chapel. Fortunately, it never arrived.\"" }
entries[206566] = { ["name"] = "Reins of the Scarlet Pterrordax", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Scarlet Pterrordax.\nSummons and dismisses your Scarlet Pterrordax.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This pterrordax was so eager to take to the skies that its handler couldn't finish training it.\"\nQuest:\nTime to Fly" }
entries[206567] = { ["name"] = "Harbor Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Harbor Gryphon.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This gryphon was the runt of its pride, left behind when its brethren were sent for training. Today, however, it is ready to prove its worth.\"\nQuest:\nTime to Fly" }
