entries[206577] = { ["name"] = "Slime-Covered Scroll", ["text"] = "Binds when picked up\nUse: Reveal a random Ancient Recipe from Naxxramas.\n\"No refunds!\"" }
entries[206578] = { ["name"] = "An Antlered Skull", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Despite the timeline this came from, this skull remains inexplicably free of fel energy. You feel an odd sense of calm while holding it.\"" }
entries[206579] = { ["name"] = "Phylacterweave", ["text"] = "Binds to Warband\nUnique (1400)\nCrafting Reagent\n\"Its soul-absorbent properties make it a crucial component for purifying Desecrated items.\"" }
entries[206581] = { ["name"] = "Harvester Core", ["text"] = "Binds when picked up" }
entries[206582] = { ["name"] = "Peculiar Glacial Mantle", ["text"] = "Binds when equipped\nShoulder Cloth\n3 Armor\n+2 Intellect\n+4 Stamina\n+3 Frost Resistance\nDurability 100 / 100\nSell Price:" }
entries[206583] = { ["name"] = "Ancient Pattern: Peculiar Glacial Mantle", ["text"] = "Use: Teaches you how to craft Peculiar Glacial Mantle.\nRequires Classic Tailoring (300)\nSell Price:\nPeculiar Glacial Mantle\nBinds when equipped\nShoulder Cloth\n3 Armor\n+2 Intellect\n+4 Stamina\n+3 Frost Resistance\nDurability 100 / 100\nSell Price:\nRequires Frozen Rune (10), Bolt of Runecloth (12), Essence of Water (9), Ironweb Spider Silk (12)" }
