entries[206585] = { ["name"] = "Reins of Valiance", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Valiance.\nSummons and dismisses Valiance.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Most undead steeds have their riders chosen for them. Valiance, on the other hand, chooses its own rider.\"\nDiscovery:\nValiance\nLocation:\nNaxxramas" }
entries[206586] = { ["name"] = "Epoch Extractor", ["text"] = "Quest Item\nUse: Drain Time-Lost Essence from defeated Time-Lost creatures within 15 yards of you. (3 Sec Cooldown)\n\"A device that allows you to steal the essence of time-lost creatures.\"" }
