entries[206596] = { ["name"] = "Tome of Thomas Thomson", ["text"] = "Quest Item\nUnique\n\"A well-worn tome with the name Thomson scrawled on the cover.\"\n<Right Click to Read>" }
entries[206598] = { ["name"] = "Smoldering Blossom", ["text"] = "Quest Item\n\"Eternally burning, yet unable to die. The Aspects will want to see this.\"" }
entries[206599] = { ["name"] = "Azmerlothian Hourglass", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The sands of this hourglass appear to float in place, suspended in time. The iconography decorating it is nearly identical to the more familiar bronze dragonflight hourglasses you are used to, only with more murlocs.\"" }
