entries[206602] = { ["name"] = "Mechanized Cog", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"This cog seems to whirl back and forth a bit, despite no longer being part of a mechanism. Into its side is etched \"Mechanization is the only way to true peace.\"\"" }
