entries[206645] = { ["name"] = "Cursed Cloth", ["text"] = "Binds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Mage, Priest, or Warlock who is willing to acquire the necessary reagents.\nSell Price:" }
