entries[206653] = { ["name"] = "Fel Pinecone", ["text"] = "Binds when picked up\nUnique (4)\nRequires level 70 to 70 ( 70)\n\"Fel, foul, rotten - perfect for stuffing up a fel cannon!\"" }
entries[206670] = { ["name"] = "Darkroot Grippers", ["text"] = "Binds when picked up\nUnique (20)\nUse: Wear a pair of Darkroot Grippers over your armor allowing you to pull Shadowrooted Vines out of the ground.\n\nVines can be found in the Fungal Field and nearby keyflame areas. (5 Sec Cooldown)\n\"Tough armored gloves to grasp lasher vines safely.\"" }
entries[206671] = { ["name"] = "Obsidian Gladiator's Halberd", ["text"] = "Binds when picked up\nTwo-Hand Polearm\n836 - 1,553 Damage Speed 3.60\n(331.8 damage per second)\n+441 Strength\n+1,295 Stamina\n+ 207 Haste\n+ 517 Versatility\nDurability 120 / 120\nSell Price:" }
entries[206673] = { ["name"] = "Horn of the White War Wolf", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Can a wolf's hunger ever be satiated? These lupine brutes seek and devour the enemies of the Horde.\"\nHorde\nDrop:\nTime Rifts\nVendor:\nWarden Krizzik\nZone:\nTyrhold Reservoir\nCost:\n3000\n\nAlliance\nItem:\nGift of the White War Wolf" }
entries[206674] = { ["name"] = "Reins of the Ravenous Black Gryphon", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon a Ravenous Black Gryphon.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"War corrupted these once-proud creatures. The susurration of their wings now whispers omens of imminent demise.\"\nAlliance\nDrop:\nTime Rifts\nVendor:\nWarden Krizzik\nZone:\nTyrhold Reservoir\nCost:\n3000\n\nHorde\nItem:\nGift of the Ravenous Black Gryphon" }
entries[206675] = { ["name"] = "Gold-Toed Albatross", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Soaring from a distant timeway, this never-before-seen avian variant was born in a world of order.\"\nDrop:\nTime Rifts\nVendor:\nSorotis\nZone:\nTyrhold Reservoir\nCost:\n3000" }
entries[206676] = { ["name"] = "Felstorm Dragon", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Burning Legion defeated dragons in a distant timeway. These foul fel wyrms chose corruption and servitude over destruction.\"\nDrop:\nTime Rifts\nVendor:\nFalara Nightsong\nZone:\nTyrhold Reservoir\nCost:\n3000" }
entries[206678] = { ["name"] = "Sulfur Hound's Leash", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Black Empire subjugated these humbled and hateful hounds. Utterly obedient, they still serve the strong.\"\nDrop:\nTime Rifts\nVendor:\nProvisioner Qorra\nZone:\nTyrhold Reservoir\nCost:\n3000" }
entries[206679] = { ["name"] = "Perfected Juggernaut", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon Perfected Juggernaut. This is a ground mount.\nSummons and dismisses Juggernaut Perfected.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Perfection, like beauty, is in the eye of the beholder. But eyesight can be surgically enhanced.\"\nDrop:\nTime Rifts\nVendor:\nGill the Drill\nZone:\nTyrhold Reservoir\nCost:\n3000" }
entries[206680] = { ["name"] = "Reins of the Scourgebound Vanquisher", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Once bound in service to the Scourge, these undead dragons exist only to spread death, disease, and destruction.\"\nDrop:\nTime Rifts\nVendor:\nBaron Silver\nZone:\nTyrhold Reservoir\nCost:\n3000" }
entries[206681] = { ["name"] = "Letter from Oman", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 30 to 70 ( 70)" }
entries[206682] = { ["name"] = "Rusziona", ["text"] = "Binds when picked up\nUse: Call Rusziona so you can have adventures together.\nCall Rusziona so you can have adventures together.\nRequires level 1 to 80 ( 80)\nSell Price:" }
entries[206683] = { ["name"] = "Wrathion's Tab", ["text"] = "Quest Item\n\"Wrathion's (rather pricy) tab, featuring enough firewine for a banquet.\"" }
entries[206695] = { ["name"] = "Pale Duskblossom", ["text"] = "Quest Item\n\"A favorite flower of Tyrande Whisperwind, remembered fondly from her youth in Val'sharah.\"" }
entries[206696] = { ["name"] = "Tricked-Out Thinking Cap", ["text"] = "Secrets of Azeroth\nBinds when picked up\nToy\nUse: Equip your Tricked-Out Thinking Cap to start tracking coordinates from your location, and listen for any stray thoughts.\n\nUsed to solve the Secrets of Azeroth.\n\"Equipped with a Cogs-and-Bolts-o-Meter.\"\nSell Price:" }
entries[206749] = { ["name"] = "Oil-Soaked Log Book", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Despite the oil dripping from it, there is enough legible text to provide some clue as to the nature of the timeline this came from.\"" }
