entries[206771] = { ["name"] = "Pattern: Cursed Cloth", ["text"] = "Binds to Warband\nUse: Teaches you how to craft Cursed Cloth.\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Tailoring (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\nCursed Cloth\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Mage, Priest, or Warlock who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Felcloth (20), Essence of Undeath (6), Dark Rune (2), Frozen Rune" }
entries[206772] = { ["name"] = "Pattern: Languished Leather", ["text"] = "Binds to Warband\nUse: Teaches you how to craft Languished Leather.\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Leatherworking (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\nLanguished Leather\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Druid or Rogue who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune" }
entries[206773] = { ["name"] = "Pattern: Scourged Scales", ["text"] = "Binds to Warband\nUse: Teaches you how to craft Scourged Scales.\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Leatherworking (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\nScourged Scales\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Hunter or Shaman who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune" }
entries[206774] = { ["name"] = "Plans: Undeath Metal", ["text"] = "Binds to Warband\nUse: Teaches you how to craft Undeath Metal.\nThis cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Blacksmithing (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\nUndeath Metal\nBinds when picked up\nUse: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\nThe resulting item will become Warbound and the desecration can be purified by a Paladin or Warrior who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Arcanite Bar (10), Essence of Undeath (6), Dark Rune (2), Frozen Rune" }
