entries[206956] = { ["name"] = "Paracausal Fragment of Sulfuras", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+396 [Agility or Strength]\nEquip: Your melee swings have a chance to deal 9875 additional Fire damage. Your harmful melee abilities have a chance to make the Fragment erupt, dealing 8229 Fire damage split between all nearby enemies. The Fragment also has a chance to react to your damage taken, counterattacking for 9875 Fire damage.\nSell Price:" }
entries[206957] = { ["name"] = "Boffins", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"This little robot happily jumped into your arms as you picked it up. It buzzes happily in your pack and almost sounds like it's purring.\"" }
entries[206958] = { ["name"] = "Paracausal Fragment of Val'anyr", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+396 Intellect\nEquip: Your healing spells have a chance to grant you Blessing of Eternal Kings for 15 sec, allowing your heals to shield the target up to ten times for 10980 damage. The shield lasts for 8 sec.\nSell Price:" }
entries[206959] = { ["name"] = "Spark of Dreams", ["text"] = "Dragonflight Season 3\nBinds when picked up\nOptional Crafting Reagent\n\n\"A powerful spark influenced by the Dream, this unique crafting material can help an item achieve expertise beyond that of mortal ability.\"\nSell Price:" }
